UPDATE email_sequences
SET
  name = 'VantoOS Executive Beta — 12 Days / 12 Pages',
  steps = steps::jsonb || '[
    {"type":"wait","duration_hours":24},
    {"type":"send_email","from_name":"VantoOS Team","subject":"Day 12: Win More Tenders with TenderOS — Your Bid Command Centre 🏛️","content":"<p style=\"background:#f0f0ff;border-left:4px solid #6366f1;padding:12px 16px;margin-bottom:20px;font-size:13px;color:#334155;line-height:1.6;\"><strong>🟣 VantoOS Executive Beta</strong><br/>You''re part of a private 20-person cohort testing an executive system built for South African leaders. Each day you''ll explore one page and complete one 10-minute task. Your feedback will directly shape the product.</p><p>Hi {{first_name}},</p><p>If you bid on government or corporate tenders, this is the feature you''ve been waiting for. TenderOS turns the chaos of tender management into a structured, AI-assisted process.</p><p>👉 <a href=\"https://executive.onlinecourseformlm.com/projects\">https://executive.onlinecourseformlm.com/projects</a> (create a new project → select \"TenderOS\" as the solution type)</p><p><strong>HERE''S HOW TO GET STARTED:</strong></p><p><strong>1️⃣ CREATE A TENDER PROJECT</strong></p><ul><li>Go to Projects → \"+ New Project\"</li><li>Give it the tender name (e.g., \"DOH Medical Supplies RFQ 2026\")</li><li>Select \"TenderOS\" as the solution type</li></ul><p><strong>2️⃣ UPLOAD THE TENDER DOCUMENT</strong></p><ul><li>Open your new TenderOS project</li><li>Go to the \"Tender Brief\" tab and upload the actual tender PDF</li><li>The AI will read the document and extract:<ul><li>Key requirements (mandatory vs optional)</li><li>Submission deadlines</li><li>Compliance documents needed</li><li>Evaluation criteria and weightings</li></ul></li></ul><p><strong>3️⃣ CHECK YOUR BID READINESS SCORE</strong></p><ul><li>VantoOS calculates a real-time Bid Readiness Score based on:<ul><li>40% Requirements coverage — have you addressed every requirement?</li><li>40% Compliance — are your documents (BEE cert, tax clearance, CSD registration) uploaded and valid?</li><li>20% Pricing — is your pricing model complete?</li></ul></li><li>Your score updates as you work, so you always know where you stand</li></ul><p><strong>4️⃣ COMPLIANCE VAULT</strong></p><ul><li>Upload your compliance documents (BEE certificate, tax clearance, company registration, etc.)</li><li>VantoOS tracks expiry dates and warns you before anything lapses</li><li>No more losing bids because of an expired document!</li></ul><p><strong>5️⃣ AI TENDER ASSISTANT</strong></p><ul><li>Ask the AI questions about the tender document:<ul><li>\"What are the mandatory requirements?\"</li><li>\"Summarise the evaluation criteria\"</li><li>\"What compliance documents do I need?\"</li></ul></li><li>Every AI answer includes citations from the actual tender document — zero hallucination, fully grounded</li></ul><p>💡 <strong>TIP:</strong> Pin your active tenders to keep them at the top of your Projects list. Use the deadline reminders to never miss a submission date.</p><p>🎉 <strong>That''s the end of your onboarding journey!</strong> You now know every major feature in VantoOS.</p><p>Remember:</p><ul><li>❓ Help button on every page for step-by-step guidance</li><li>📖 User Manual: <a href=\"https://executive.onlinecourseformlm.com/manual\">https://executive.onlinecourseformlm.com/manual</a></li><li>🤖 Your AI Portfolio Partner gets smarter the more you use VantoOS</li></ul><p>Welcome to the future of executive productivity.</p><p>The VantoOS Team</p>"}
  ]'::jsonb,
  updated_at = now()
WHERE id = '0f23eef6-6c16-4f9f-9357-8a67e358abe2';
